pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }
    function testRegression_property() public {
        address admin = address(0x1234);
        c.adjustAdminAccess(admin, true);

        vm.prank(admin);
        c.createGameItem("Item", "ipfs://test", false, true, 100, 1 ether, 10);

        uint256 balance = c.balanceOf(address(this), 0);

        assertTrue(balance == 0, "Expected balance to be 0");
    }
}
